exec(open('/home/claude/work/gita/gc.py').read())
FLD=lambda lab,cap: S(lab,'',None,cap,FIELD,person(70,130,'#ffd60a','#c98b5a',1.4)+GLOW(70,90,16,'#ffd60a',.9)+'<rect x="120" y="70" width="80" height="60" fill="#c9a26b" stroke="#111" stroke-width="2"/>'+T(160,104,'FIELD',11))
V=[
X(1,'THE FIELD AND ITS KNOWER',
 FLD('A body drawn as a field, a glowing knower watching it','KṢETRA · KṢETRAJÑA'),
 'The Lord said: This body, son of Kuntī, is called the field (kṣetra); the one who knows it is called the knower of the field (kṣetrajña) by those who know.',
 [('idam śarīram kaunteya','<b>this body, son of Kuntī</b>'),('kṣetram iti abhidhīyate','<b>is called the field</b>'),('etat yaḥ vetti','<b>the one who knows it</b>'),('kṣetrajñaḥ iti tat-vidaḥ','<b>is called the knower of the field, by the wise</b>')],
 'The third part of the Gītā, on knowledge, begins. Body = field; the one aware of it = knower of the field.',
 'Some editions add a verse before this, in which Arjuna asks about prakṛti, puruṣa, the field, the knower, knowledge and the knowable (shown as 13.0 in the In One Go pages). The Gītā Press text omits it, keeping the total at 700. The image of the field is apt: things grow in it according to what is sown, as actions bear fruit in the body.',
 'You have a body; you are aware of it. Notice the difference: the one aware is not the same as what it is aware of.',
 'The body is the field; <b>you are its knower</b>.',
 note='An extra verse (“arjuna uvāca: prakṛtiṃ puruṣaṃ caiva…”) found in some editions is printed as 13.0 in the In One Go pages; it is not counted in the 700.'),
X(2,'I AM THE KNOWER IN ALL FIELDS',
 S('Krishna as the same light inside many bodies','K','family','IN ALL FIELDS'),
 '“And know me also as the knower of the field in all fields, Bhārata. The knowledge of the field and its knower: that, I hold, is true knowledge.”',
 [('kṣetrajñam ca api mām viddhi','<b>know me also as the knower</b>'),('sarva-kṣetreṣu bhārata','<b>in all fields</b>'),('kṣetra-kṣetrajñayoḥ jñānam','<b>knowledge of field and knower</b>'),('yat tat jñānam matam mama','<b>that is knowledge, in my view</b>')],
 'Kṛṣṇa says he is the knower in every body.',
 'A key verse for Vedānta. Śaṅkara reads it as the identity of the individual knower with the Lord: one consciousness in all. Rāmānuja reads it as the Lord dwelling as the inner controller (antaryāmin) of each distinct self. Both agree real knowledge is knowing this distinction between body and knower.',
 'The same awareness that looks through your eyes looks through every eye. That can change how you see others.',
 'I am the knower <b>in every field</b>.'),
X(3,'HEAR IT IN BRIEF',
 S('Krishna about to explain the field and its knower','K','book','IN BRIEF'),
 '“What that field is, what it is like, what its changes are, where it comes from; and who that knower is and what his powers are: hear that from me in brief.”',
 [('tat kṣetram yat ca yādṛk ca','<b>what that field is, what it is like</b>'),('yat-vikāri yataḥ ca yat','<b>what its changes, whence it is</b>'),('saḥ ca yaḥ yat-prabhāvaḥ ca','<b>who he is, what his powers</b>'),('tat samāsena me śṛṇu','<b>hear that briefly from me</b>')],
 'Kṛṣṇa outlines what he will explain.',
 'Six topics: the field, its nature, its changes, its origin, the knower, and his powers. Commentators note the systematic style of this chapter, closer to philosophy than to story.',
 'Clear questions make clear answers. Kṛṣṇa organises before he teaches.',
 'Six things <b>to understand</b>.'),
X(4,'AS THE SAGES SANG',
 S('Sages singing hymns, a scroll of the Brahma Sutras','','sage','ṚṢIBHIḤ'),
 '“It has been sung by sages in many ways, in various distinct hymns, and also in the well-reasoned, conclusive words of the Brahma-sūtras.”',
 [('ṛṣibhiḥ bahudhā gītam','<b>sung by sages in many ways</b>'),('chandobhiḥ vividhaiḥ pṛthak','<b>in various distinct hymns</b>'),('brahma-sūtra-padaiḥ ca eva','<b>and in the words of the Brahma-sūtras</b>'),('hetumadbhiḥ viniścitaiḥ','<b>reasoned and decisive</b>')],
 'The teaching has been given before, in the Vedas and in reasoned texts.',
 '“Brahma-sūtra” here may mean Bādarāyaṇa’s Brahma Sūtras or, more broadly, Upaniṣadic statements about Brahman. Commentators differ; Śaṅkara takes it as Upaniṣadic sayings. The Gītā places itself within a tradition of reasoned inquiry.',
 'Good teaching agrees with both scripture and reason.',
 'Sung by sages, <b>proved by reason</b>.'),
X(5,'WHAT THE FIELD IS MADE OF · I',
 S('The parts of the field: elements, ego, intellect, senses','','guna','24 PARTS'),
 '“The great elements, ego, intellect and the unmanifest; the ten senses and the one (mind), and the five objects of the senses;”',
 [('mahā-bhūtāni ahaṅkāraḥ','<b>the great elements, ego</b>'),('buddhiḥ avyaktam eva ca','<b>intellect and the unmanifest</b>'),('indriyāṇi daśa ekam ca','<b>the ten senses and the one</b>'),('pañca ca indriya-gocarāḥ','<b>and the five sense-objects</b>')],
 'The field is made of the 24 principles of Sāṅkhya.',
 'Count: 5 elements + ego + intellect + unmanifest nature = 8; 10 senses (5 of knowing, 5 of action) + mind = 11; 5 sense objects. Total 24. Commentators say even mind and ego are part of the field, not the knower.',
 'Your thoughts and your sense of “I” are part of the field. The knower watches them.',
 'The field: <b>24 principles</b>.'),
X(6,'WHAT THE FIELD IS MADE OF · II',
 S('Desire, aversion, pleasure, pain, the body, awareness, will','','mind','AND ITS CHANGES'),
 '“…desire, aversion, pleasure, pain, the body, awareness, steadfastness: this, in brief, is the field with its modifications.”',
 [('icchā dveṣaḥ sukham duḥkham','<b>desire, aversion, pleasure, pain</b>'),('saṅghātaḥ cetanā dhṛtiḥ','<b>the aggregate, awareness, firmness</b>'),('etat kṣetram samāsena','<b>this is the field in brief</b>'),('sa-vikāram udāhṛtam','<b>with its modifications, declared</b>')],
 'Even feelings and awareness of the mind belong to the field.',
 'Surprising: desire, pain, even <i>cetanā</i> (awareness as a mental state) are “field”. Commentators distinguish the mind’s awareness, a changing state, from the knower, pure unchanging consciousness.',
 'Your moods are part of the field, not the knower. That gives some distance from them.',
 'Feelings too <b>are part of the field</b>.'),
X(7,'WHAT KNOWLEDGE LOOKS LIKE · I',
 S('A humble person serving a teacher, gentle and upright','P','sage','AMĀNITVAM'),
 '“Humility, unpretentiousness, non-violence, patience, uprightness, service of the teacher, purity, steadfastness, self-control,”',
 [('amānitvam adambhitvam','<b>humility, unpretentiousness</b>'),('ahiṃsā kṣāntiḥ ārjavam','<b>non-violence, patience, uprightness</b>'),('ācārya-upāsanam śaucam','<b>serving the teacher, purity</b>'),('sthairyam ātma-vinigrahaḥ','<b>steadiness, self-control</b>')],
 'Verses 13.7–11 list twenty marks of knowledge. Knowledge is a way of living, not only information.',
 'This list is famous for defining knowledge by character. Humility comes first. Commentators say these are both means to knowledge and signs of it.',
 'Real knowledge shows in humility and kindness, not in cleverness.',
 'Knowledge begins <b>with humility</b>.'),
X(8,'WHAT KNOWLEDGE LOOKS LIKE · II',
 S('A person seeing birth, old age, sickness and death clearly','P','death','SEEING CLEARLY'),
 '“…dispassion toward the objects of the senses, absence of ego, and seeing the evil of birth, death, old age, sickness and pain,”',
 [('indriya-artheṣu vairāgyam','<b>dispassion toward sense objects</b>'),('anahaṅkāraḥ eva ca','<b>and absence of ego</b>'),('janma-mṛtyu-jarā-vyādhi','<b>birth, death, old age, sickness</b>'),('duḥkha-doṣa-anudarśanam','<b>seeing the fault of pain</b>')],
 'Seeing life’s sorrows clearly is part of wisdom.',
 'This recalls the Buddha’s four sights: old age, sickness, death and a renunciant. Commentators say clear seeing of suffering loosens attachment.',
 'Facing ageing and illness honestly can make us wiser and kinder.',
 'See birth, age, <b>sickness and death</b> clearly.'),
X(9,'WHAT KNOWLEDGE LOOKS LIKE · III',
 S('A person loving family without clinging, calm in good and bad','P','family','ASAKTI'),
 '“…non-attachment, not clinging to son, wife, home and the like, and constant evenness of mind in desired and undesired events,”',
 [('asaktiḥ','<b>non-attachment</b>'),('anabhiṣvaṅgaḥ putra-dāra-gṛha-ādiṣu','<b>not clinging to son, wife, home</b>'),('nityam ca sama-cittatvam','<b>constant evenness of mind</b>'),('iṣṭa-aniṣṭa-upapattiṣu','<b>in wanted and unwanted events</b>')],
 'Love family, but don’t cling.',
 'Commentators distinguish love from clinging: one can care deeply without the anxiety of possession. <i>Abhiṣvaṅga</i> is excessive identification, feeling that their joys and griefs are one’s own.',
 'Love fully, hold lightly. It is better for everyone.',
 'Love <b>without clinging</b>.'),
X(10,'WHAT KNOWLEDGE LOOKS LIKE · IV',
 S('A devotee in a quiet place, away from crowds','Y','tree','VIVIKTA-DEŚA'),
 '“…unwavering devotion to me with undivided yoga, resorting to solitary places, distaste for crowds,”',
 [('mayi ca ananya-yogena','<b>and to me, with undivided yoga</b>'),('bhaktiḥ avyabhicāriṇī','<b>unwavering devotion</b>'),('vivikta-deśa-sevitvam','<b>resorting to solitary places</b>'),('aratiḥ jana-saṃsadi','<b>distaste for crowds</b>')],
 'Devotion and solitude are marks of knowledge.',
 'Note bhakti is part of the list of knowledge: the Gītā does not separate them. Commentators say “distaste for crowds” means avoiding idle company, not people.',
 'Find time alone with yourself and the Divine.',
 'Devotion <b>and quiet</b>.'),
X(11,'WHAT KNOWLEDGE LOOKS LIKE · V',
 S('A seeker gazing steadily at the light of truth','Y','light','TATTVA-JÑĀNA'),
 '“…constancy in knowledge of the Self, insight into the goal of true knowledge: this is declared to be knowledge; what is contrary to it is ignorance.”',
 [('adhyātma-jñāna-nityatvam','<b>constancy in Self-knowledge</b>'),('tattva-jñāna-artha-darśanam','<b>seeing the aim of true knowledge</b>'),('etat jñānam iti proktam','<b>this is called knowledge</b>'),('ajñānam yat ataḥ anyathā','<b>the opposite is ignorance</b>')],
 'The list ends: all this is knowledge; the opposite is ignorance.',
 'A bold definition: arrogance, violence, impatience and clinging are “ignorance”, however learned the person. Commentators say this is the Gītā’s real curriculum.',
 'Measure knowledge by character. Learning without these is not wisdom.',
 'All this <b>is knowledge</b>.'),
X(12,'WHAT IS TO BE KNOWN',
 S('A beginningless light, neither being nor non-being','','om','JÑEYAM'),
 '“I will tell you what is to be known, knowing which one gains immortality: the beginningless supreme Brahman, which is said to be neither being nor non-being.”',
 [('jñeyam yat tat pravakṣyāmi','<b>what is to be known, I will tell</b>'),('yat jñātvā amṛtam aśnute','<b>knowing which one gains immortality</b>'),('anādimat param brahma','<b>the beginningless supreme Brahman</b>'),('na sat tat na asat ucyate','<b>neither being nor non-being, it is said</b>')],
 'Now the object of knowledge: Brahman.',
 'Brahman is beyond categories: not “being” as a thing exists, nor “non-being”. Commentators: words point but cannot capture. The following verses describe it in paradoxes.',
 'Some truths are beyond yes and no. Paradox is a way of pointing.',
 'Neither being <b>nor non-being</b>.'),
X(13,'HANDS AND FEET EVERYWHERE',
 S('A vast presence with hands, eyes and ears in every direction','','cosmic','SARVATAḤ'),
 '“With hands and feet everywhere, with eyes, heads and mouths everywhere, with ears everywhere, it dwells in the world, enveloping all.”',
 [('sarvataḥ pāṇi-pādam tat','<b>with hands and feet everywhere</b>'),('sarvataḥ akṣi-śiraḥ-mukham','<b>eyes, heads, mouths everywhere</b>'),('sarvataḥ śrutimat loke','<b>with ears everywhere in the world</b>'),('sarvam āvṛtya tiṣṭhati','<b>it stands enveloping all</b>')],
 'Brahman works through every hand and sees through every eye.',
 'This verse is taken almost word for word from the Śvetāśvatara Upaniṣad (3.16). Commentators: all hands and eyes are its instruments.',
 'Every helping hand you see is, in a sense, the Divine at work.',
 'Hands and eyes <b>everywhere</b>.'),
X(14,'WITHOUT SENSES, YET SENSING',
 S('A light shining through senses but needing none','','light','PARADOX'),
 '“Shining through the functions of all the senses, yet free of all senses; unattached, yet supporting all; free of the guṇas, yet the experiencer of the guṇas.”',
 [('sarva-indriya-guṇa-ābhāsam','<b>shining through all sense-functions</b>'),('sarva-indriya-vivarjitam','<b>yet free of all senses</b>'),('asaktam sarva-bhṛt ca eva','<b>unattached yet supporting all</b>'),('nirguṇam guṇa-bhoktṛ ca','<b>without guṇas, yet enjoying guṇas</b>')],
 'A chain of paradoxes.',
 'Also from the Śvetāśvatara Upaniṣad (3.17). Commentators: consciousness lights up all experience without being any sense; it supports all without clinging.',
 'Awareness is in every experience, yet is none of them. Notice that.',
 'Free of senses, <b>yet lighting them</b>.'),
X(15,'FAR AND NEAR',
 S('A light both inside and outside beings, far and near','','light','DŪRA · ANTIKA'),
 '“Outside and inside all beings; unmoving and moving; too subtle to be known; far away and yet near.”',
 [('bahiḥ antaḥ ca bhūtānām','<b>outside and inside beings</b>'),('acaram caram eva ca','<b>unmoving and moving</b>'),('sūkṣmatvāt tat avijñeyam','<b>being subtle, it is unknowable</b>'),('dūra-stham ca antike ca tat','<b>it is far and also near</b>')],
 'Brahman is both distant and closest.',
 'This echoes the Īśa Upaniṣad (5): “it is far, it is near; it is within all, it is outside all.” Commentators: far for the ignorant, nearest for the wise.',
 'What seems far may be closer than your breath.',
 'Far, <b>yet near</b>.'),
X(16,'UNDIVIDED, YET AS IF DIVIDED',
 S('One light appearing as many small lights','','star','AVIBHAKTA'),
 '“Undivided, yet it seems divided among beings; it is to be known as the sustainer of beings, their devourer and their creator.”',
 [('avibhaktam ca bhūteṣu','<b>undivided among beings</b>'),('vibhaktam iva ca sthitam','<b>yet seeming divided</b>'),('bhūta-bhartṛ ca tat jñeyam','<b>know it as sustainer of beings</b>'),('grasiṣṇu prabhaviṣṇu ca','<b>devourer and creator</b>')],
 'One reality appearing as many.',
 'Commentators use the image of the sun reflected in many pots of water: many suns appear, but there is one. Creator, sustainer, destroyer: the three functions in one.',
 'Beneath differences, one reality. Above differences, respect.',
 'One, <b>appearing as many</b>.'),
X(17,'LIGHT OF LIGHTS',
 S('A light beyond darkness shining in every heart','','light','JYOTIṢĀM JYOTIḤ'),
 '“It is the light of lights, said to be beyond darkness. It is knowledge, what is to be known, and the goal of knowledge, seated in the hearts of all.”',
 [('jyotiṣām api tat jyotiḥ','<b>the light of lights</b>'),('tamasaḥ param ucyate','<b>said to be beyond darkness</b>'),('jñānam jñeyam jñāna-gamyam','<b>knowledge, the known, the goal of knowledge</b>'),('hṛdi sarvasya viṣṭhitam','<b>seated in the heart of all</b>')],
 'The light by which all lights are seen.',
 'Even the sun is seen by awareness. Commentators echo the Muṇḍaka and Kaṭha Upaniṣads: “by its light all this shines”. And it is in every heart.',
 'The light you seek is the light you see with.',
 'The <b>light of lights</b>, in every heart.'),
X(18,'MY DEVOTEE WHO KNOWS',
 S('A devotee understanding field, knowledge and the knowable, reaching Krishna','KA','heart','MAT-BHĀVA'),
 '“Thus the field, knowledge and the knowable have been described briefly. My devotee, understanding this, attains my state.”',
 [('iti kṣetram tathā jñānam','<b>thus the field and knowledge</b>'),('jñeyam ca uktam samāsataḥ','<b>and the knowable, told in brief</b>'),('mat-bhaktaḥ etat vijñāya','<b>my devotee, knowing this</b>'),('mat-bhāvāya upapadyate','<b>attains my state</b>')],
 'A summary, and a promise to the devotee.',
 'Commentators note “my devotee”: even in the knowledge chapters, devotion is the frame.',
 'Knowledge and love together lead home.',
 'My devotee <b>who knows, attains me</b>.'),
X(19,'NATURE AND SPIRIT',
 S('Two beginningless principles: prakriti in colours, purusha as light','','guna','PRAKṚTI · PURUṢA'),
 '“Know that prakṛti (nature) and puruṣa (spirit) are both beginningless; and know that modifications and guṇas are born of prakṛti.”',
 [('prakṛtim puruṣam ca eva','<b>nature and spirit</b>'),('viddhi anādī ubhau api','<b>know both as beginningless</b>'),('vikārān ca guṇān ca eva','<b>modifications and guṇas</b>'),('viddhi prakṛti-sambhavān','<b>know as born of nature</b>')],
 'Two principles, both without beginning.',
 'This uses Sāṅkhya terms. In classical Sāṅkhya they are fully separate; the Gītā places both under the Lord (7.4–5). Commentators note both are “beginningless”: the world-process has no first moment.',
 'You are spirit living in nature. Both are old beyond counting.',
 'Nature and spirit, <b>both beginningless</b>.'),
X(20,'WHO DOES, WHO EXPERIENCES',
 S('Nature doing the actions, spirit feeling pleasure and pain','','scale','DOER · EXPERIENCER'),
 '“Prakṛti is said to be the cause of cause and effect in body and senses; puruṣa is said to be the cause of the experience of pleasure and pain.”',
 [('kārya-kāraṇa-kartṛtve','<b>in producing body and instruments</b>'),('hetuḥ prakṛtiḥ ucyate','<b>nature is called the cause</b>'),('puruṣaḥ sukha-duḥkhānām','<b>spirit, of pleasure and pain</b>'),('bhoktṛtve hetuḥ ucyate','<b>is called the cause of experiencing</b>')],
 'Nature acts; spirit experiences.',
 'Commentators: the body and mind do; consciousness feels. Confusing the two is the root of bondage.',
 'Your body acts; you experience. Watching both creates space.',
 'Nature acts, <b>spirit experiences</b>.'),
X(21,'WHY WE ARE BORN',
 S('Spirit seated in nature, drawn by guna-attachment into many births','','wheel','GUṆA-SAṄGA'),
 '“Puruṣa, seated in prakṛti, experiences the guṇas born of prakṛti. Attachment to the guṇas is the cause of its birth in good and evil wombs.”',
 [('puruṣaḥ prakṛti-sthaḥ hi','<b>spirit, seated in nature</b>'),('bhuṅkte prakṛti-jān guṇān','<b>experiences nature-born guṇas</b>'),('kāraṇam guṇa-saṅgaḥ asya','<b>attachment to guṇas is the cause</b>'),('sat-asat-yoni-janmasu','<b>of birth in good and evil wombs</b>')],
 'Attachment to nature’s qualities causes rebirth.',
 'The cause of bondage is not nature itself but <i>saṅga</i>, attachment. Commentators: cut the attachment and the cycle loosens.',
 'It is not the world that binds but our clinging to it.',
 'Attachment <b>causes rebirth</b>.'),
X(22,'THE SUPREME SELF IN THE BODY',
 S('A witness, supporter and Lord seated within the body','','light','PARAMĀTMĀ'),
 '“The supreme Person in this body is called the witness, the one who permits, the supporter, the experiencer, the great Lord, and the supreme Self.”',
 [('upadraṣṭā anumantā ca','<b>the witness and permitter</b>'),('bhartā bhoktā maheśvaraḥ','<b>supporter, experiencer, great Lord</b>'),('paramātmā iti ca api uktaḥ','<b>also called the supreme Self</b>'),('dehe asmin puruṣaḥ paraḥ','<b>the supreme Person in this body</b>')],
 'Six names for the Supreme within.',
 'A rich verse: witness (sees all), permitter (allows), supporter, experiencer, Lord, supreme Self. Rāmānuja reads this as the Lord within the soul; Śaṅkara as the soul’s true nature.',
 'Within you is a witness who sees all and judges gently.',
 'The supreme Self <b>within the body</b>.'),
X(23,'WHOEVER KNOWS THIS',
 S('A person living ordinary life, knowing spirit and nature, free','P','light','NA JĀYATE'),
 '“One who knows puruṣa and prakṛti together with the guṇas in this way, however he may live, is not born again.”',
 [('yaḥ evam vetti puruṣam','<b>who thus knows spirit</b>'),('prakṛtim ca guṇaiḥ saha','<b>and nature with the guṇas</b>'),('sarvathā vartamānaḥ api','<b>however he may live</b>'),('na saḥ bhūyaḥ abhijāyate','<b>is not born again</b>')],
 'Knowledge frees, whatever one’s outer life.',
 '“However he may live”: commentators caution this does not license wrong action; one who truly knows does not act wrongly. It means outer circumstances do not limit freedom.',
 'Freedom is possible in any life situation.',
 'Knowing this, <b>no more rebirth</b>.'),
X(24,'MANY WAYS TO SEE THE SELF',
 S('A meditator, a thinker and a worker all seeing the Self','','light','DHYĀNA · SĀṄKHYA · KARMA'),
 '“Some see the Self in the self by the self through meditation; others by the yoga of knowledge; and others by the yoga of action.”',
 [('dhyānena ātmani paśyanti','<b>by meditation, see in the self</b>'),('kecit ātmānam ātmanā','<b>some, the Self by the self</b>'),('anye sāṅkhyena yogena','<b>others by the yoga of knowledge</b>'),('karma-yogena ca apare','<b>and others by karma yoga</b>')],
 'Three paths to the same vision.',
 'Meditation, knowledge and action: the paths of chapters 6, 2 and 3. Commentators: different temperaments, one goal.',
 'Find the path that suits you, and walk it.',
 'Many paths, <b>one vision</b>.'),
X(25,'THOSE WHO HEAR AND WORSHIP',
 S('People listening to teachers and worshipping with faith','P','book','ŚRUTI-PARĀYAṆĀḤ'),
 '“Yet others, not knowing this, hear it from others and worship. They too cross beyond death, devoted to what they have heard.”',
 [('anye tu evam ajānantaḥ','<b>but others, not knowing thus</b>'),('śrutvā anyebhyaḥ upāsate','<b>hearing from others, worship</b>'),('te api ca atitaranti eva','<b>they too cross over</b>'),('mṛtyum śruti-parāyaṇāḥ','<b>death, devoted to what they heard</b>')],
 'Even those who simply trust and follow cross over.',
 'A generous verse for the ordinary believer. Commentators: listening to the wise with faith is itself a path.',
 'You don’t need to know everything. Trust the wise and follow sincerely.',
 'Even simple faith <b>crosses over death</b>.'),
X(26,'FIELD MEETS KNOWER',
 FLD('Everything born from the meeting of field and knower','SAṂYOGA'),
 '“Whatever being is born, moving or unmoving, know it to arise from the union of the field and the knower of the field, best of the Bharatas.”',
 [('yāvat sañjāyate kiñcit','<b>whatever is born</b>'),('sattvam sthāvara-jaṅgamam','<b>being, unmoving or moving</b>'),('kṣetra-kṣetrajña-saṃyogāt','<b>from the union of field and knower</b>'),('tat viddhi bharata-ṛṣabha','<b>know that</b>')],
 'Every living thing is consciousness joined with matter.',
 'Commentators: the union is not like two objects joining, but like light falling on a surface, or a reflection. Life is where awareness meets nature.',
 'Every living being is awareness in a body. Respect both.',
 'Life is <b>spirit in matter</b>.'),
X(27,'WHO SEES TRULY',
 S('A wise person seeing the same Lord in all beings','Y','family','SAḤ PAŚYATI'),
 '“One who sees the supreme Lord dwelling equally in all beings, the imperishable in the perishing, truly sees.”',
 [('samam sarveṣu bhūteṣu','<b>equally in all beings</b>'),('tiṣṭhantam parameśvaram','<b>dwelling, the supreme Lord</b>'),('vinaśyatsu avinaśyantam','<b>the imperishable in the perishing</b>'),('yaḥ paśyati saḥ paśyati','<b>who sees thus, truly sees</b>')],
 'True vision: the same Lord in all.',
 '“He who sees, sees” (compare 5.5). Commentators of all schools prize this verse as the essence of right vision.',
 'Look for the same Light in every face, including difficult ones.',
 'Who sees the Lord in all, <b>truly sees</b>.'),
X(28,'NOT HARMING ONESELF',
 S('A person who sees God everywhere, unable to harm anyone','Y','heart','NA HINASTI'),
 '“Seeing the same Lord equally present everywhere, he does not harm the Self by the self, and so reaches the supreme goal.”',
 [('samam paśyan hi sarvatra','<b>seeing equally everywhere</b>'),('samavasthitam īśvaram','<b>the Lord equally present</b>'),('na hinasti ātmanā ātmānam','<b>does not harm the Self by the self</b>'),('tataḥ yāti parām gatim','<b>then reaches the supreme goal</b>')],
 'Seeing God everywhere, one cannot harm.',
 'To harm another is to harm the Self in them, and so oneself. Commentators also read: one who sees truly no longer “harms himself” by ignorance.',
 'Harming others harms us too. Seeing unity makes kindness natural.',
 'Seeing the Lord in all, <b>harm none</b>.'),
X(29,'NATURE ACTS, THE SELF DOES NOT',
 S('Nature’s wheels turning, the Self watching','Y','wheel','AKARTĀ'),
 '“One who sees that all actions are done by prakṛti alone, and that the Self is not the doer, truly sees.”',
 [('prakṛtyā eva ca karmāṇi','<b>by nature alone, actions</b>'),('kriyamāṇāni sarvaśaḥ','<b>being done in every way</b>'),('yaḥ paśyati tathā ātmānam','<b>who sees, and the Self</b>'),('akartāram saḥ paśyati','<b>as non-doer, he sees</b>')],
 'Another mark of true seeing: the Self is not the doer.',
 'This repeats 3.27 and 5.8–9 in the language of field and knower. Commentators: it frees from pride and guilt alike.',
 'Watch actions happen, including your own, with a little distance.',
 'The Self is <b>not the doer</b>.'),
X(30,'MANY IN ONE',
 S('Many beings resting in and spreading from one source','','tree','EKASTHAM'),
 '“When one sees the many separate states of beings as resting in the One, and spreading out from it, then one attains Brahman.”',
 [('yadā bhūta-pṛthak-bhāvam','<b>when the separate states of beings</b>'),('eka-stham anupaśyati','<b>one sees as resting in the One</b>'),('tataḥ eva ca vistāram','<b>and spreading from there</b>'),('brahma sampadyate tadā','<b>then one attains Brahman</b>')],
 'Seeing the many in the One is reaching Brahman.',
 'Like branches spreading from one trunk. Commentators: this vision is liberation itself.',
 'Look at diversity, then look for the root that holds it.',
 'The many <b>in the One</b>.'),
X(31,'NEITHER ACTS NOR IS STAINED',
 S('A light in a body, untouched by its actions','','light','NA LIPYATE'),
 '“Being beginningless and without guṇas, this imperishable supreme Self, though dwelling in the body, Kaunteya, neither acts nor is stained.”',
 [('anāditvāt nirguṇatvāt','<b>being beginningless, without guṇas</b>'),('parama-ātmā ayam avyayaḥ','<b>this imperishable supreme Self</b>'),('śarīra-sthaḥ api kaunteya','<b>though in the body</b>'),('na karoti na lipyate','<b>neither acts nor is stained</b>')],
 'The Self in the body is untouched by its actions.',
 'Commentators: because it has no beginning and no qualities, nothing can cling to it. The next verse gives an image.',
 'At your core, nothing you have done can stain what you are.',
 'In the body, <b>yet unstained</b>.'),
X(32,'LIKE SPACE',
 S('Space unchanged though filled with smoke and dust','','storm','ĀKĀŚA'),
 '“As all-pervading space, being subtle, is not stained, so the Self, present everywhere in the body, is not stained.”',
 [('yathā sarva-gatam saukṣmyāt','<b>as all-pervading, through subtlety</b>'),('ākāśam na upalipyate','<b>space is not stained</b>'),('sarvatra avasthitaḥ dehe','<b>present everywhere in the body</b>'),('tathā ātmā na upalipyate','<b>so the Self is not stained</b>')],
 'Space is not dirtied by what fills it.',
 'Smoke fills a room; when it clears, space is unchanged. Commentators love this image for the purity of the Self.',
 'Whatever passes through you, your deepest self remains clear.',
 'Like space, <b>unstained</b>.'),
X(33,'LIKE THE SUN',
 S('One sun lighting the whole world','','sun','PRAKĀŚAYATI'),
 '“As the one sun lights up this whole world, so the knower of the field lights up the whole field, Bhārata.”',
 [('yathā prakāśayati ekaḥ','<b>as the one lights up</b>'),('kṛtsnam lokam imam raviḥ','<b>this whole world, the sun</b>'),('kṣetram kṣetrī tathā kṛtsnam','<b>so the knower, the whole field</b>'),('prakāśayati bhārata','<b>lights up</b>')],
 'The knower lights up the body as the sun lights the world.',
 'Commentators: the sun shows good and bad alike without being affected. So awareness lights up all experience.',
 'Your awareness is the sun of your life. Let it shine clearly.',
 'Like the sun, <b>lighting the field</b>.'),
X(34,'THE EYE OF KNOWLEDGE',
 S('A person with the eye of wisdom seeing field and knower apart, walking free','Y','light','JÑĀNA-CAKṢUḤ'),
 '“Those who know, with the eye of knowledge, the difference between the field and the knower of the field, and the freeing of beings from prakṛti, reach the Supreme.”',
 [('kṣetra-kṣetrajñayoḥ evam','<b>of field and knower, thus</b>'),('antaram jñāna-cakṣuṣā','<b>the difference, by the eye of knowledge</b>'),('bhūta-prakṛti-mokṣam ca','<b>and freedom of beings from nature</b>'),('ye viduḥ yānti te param','<b>who know, reach the Supreme</b>')],
 'The chapter ends: seeing the difference frees.',
 'The whole chapter rests on <i>viveka</i>, discrimination between the seen and the seer. Commentators say this “eye of knowledge” is the divine eye of chapter 11 turned inward.',
 'Learn to tell apart what you have from what you are.',
 'The eye of knowledge <b>sets you free</b>.'),
]
cover=('<svg width="380" height="268" viewBox="0 0 380 268" role="img" aria-label="A ploughed field shaped like a human body, with a glowing sun-like knower above it lighting the whole field">'
 '<rect width="380" height="268" fill="#0b2a4a" rx="8"/>'+SUN(190,70,40)+GLOW(190,70,90,'#ffd60a',.2)+'<path d="M60 250 L120 150 H260 L320 250z" fill="#c9a26b" stroke="#111" stroke-width="2"/>'+''.join(f'<path d="M{110+k*20} 160 L{90+k*26} 250" stroke="#7a5a3a" stroke-width="2"/>' for k in range(8))+person(190,230,'#ffd60a','#c98b5a',1.4)+T(190,140,'KṢETRA · KṢETRAJÑA',14,'#ffd60a')+'</svg>')
P=dict(ch=13,nv=34,V=V,per=[18,17],extra0='13.0',out='/home/claude/work/gita/Gita_Chapter13.html',
 title='The Field and Its Knower · Bhagavad Gītā Chapter 13 · srini.presents',
 desc='Bhagavad Gītā chapter 13, Kṣetra Kṣetrajña Vibhāga Yoga, every śloka explained: the body as the field and the Self as its knower, twenty marks of true knowledge, Brahman as the light of lights, prakṛti and puruṣa, and seeing the Lord equally in all. All 34 ślokas in IAST, each on two pages.',
 burst='CHAPTER 13 OF 18',h1='THE FIELD AND ITS KNOWER',h1size=60,series='BHAGAVAD GĪTĀ · CHAPTER 13 · KṢETRA KṢETRAJÑA VIBHĀGA YOGA',tag='The light of lights · every śloka explained',cover=cover,
 where=[f'In {chl(12)} Kṛṣṇa described the devotee dear to him.',
  'The final six chapters turn to knowledge. Chapter 13 makes one great distinction: the body (with mind and feelings) is the field; the Self is the knower of the field. Kṛṣṇa lists twenty marks of real knowledge, beginning with humility, then describes Brahman, the light of lights in every heart, and ends: who sees the Lord equally in all, truly sees.'],
 wtalk=("Am I the body or the knower?","That is exactly the question of chapter 13. Watch where your awareness sits as you read."),
 fullnote=FULLNOTE+' Verse 13.0 is found only in some editions and is not counted in the 700.',
 secs=[('THE FIELD AND THE KNOWER',1),('WHAT IS THE FIELD',5),('TWENTY MARKS OF KNOWLEDGE',7),('WHAT IS TO BE KNOWN',12),('NATURE AND SPIRIT',19),('TRUE SEEING',24)],
 end=['<b>Field and knower (13.1–4).</b> The body is the field; the Self is its knower; knowing both is true knowledge.',
  '<b>The field (13.5–6).</b> Elements, mind, ego, senses, objects, desire, pain and the rest.',
  '<b>Knowledge (13.7–11).</b> Humility, non-violence, patience, service, purity, dispassion, love without clinging, devotion, quiet.',
  '<b>The knowable (13.12–18).</b> Brahman: hands and eyes everywhere, far and near, the light of lights in every heart.',
  '<b>Nature, spirit, seeing (13.19–34).</b> Nature acts, spirit experiences; attachment binds; who sees the Lord in all beings truly sees.'],
 endsub='Chapter 13 in five lines',
 next=("What's next?",f'{chl(14)}: The three guṇas. Sattva, rajas and tamas: how they bind, how to recognise them, and how to rise beyond them.'),
 endkey='<b>you are the knower, not the field</b>.',
 foot=FOOT(13,'Parallels with the Śvetāśvatara and Īśa Upaniṣads are noted by traditional commentators. '))
build2(P)
